// Hand-written `@nestjs/axios` stub. The response type is the call's own type
// argument, which is what makes the shape at the far end readable.

export interface AxiosResponse<Data = unknown> {
  data: Data;
  status: number;
}

export declare class HttpService {
  get<Data = unknown>(url: string, config?: unknown): { data: AxiosResponse<Data> };
  post<Data = unknown>(url: string, body?: unknown, config?: unknown): { data: AxiosResponse<Data> };
}
